-- LUCRA · várias unidades na mesma conta. Uma instrução por linha e pode rodar de novo.
create or replace function public.criar_unidade(p_nome text, p_area text, p_pessoa text) returns uuid language plpgsql security definer set search_path = public as $$ declare cid uuid; begin if auth.uid() is null then raise exception 'sem_login'; end if; if (select count(*) from membros where user_id = auth.uid() and papel = 'dono') >= 10 then raise exception 'limite_unidades'; end if; insert into clinicas (nome, area) values (coalesce(p_nome, ''), p_area) returning id into cid; insert into membros (clinica_id, user_id, papel, nome, email) values (cid, auth.uid(), 'dono', coalesce(p_pessoa, ''), coalesce(auth.jwt()->>'email', '')); insert into dados (clinica_id) values (cid); insert into clinico (clinica_id) values (cid); return cid; end $$;
revoke execute on function public.criar_unidade(text, text, text) from public, anon;
grant execute on function public.criar_unidade(text, text, text) to authenticated;
